from pathlib import Path
from librelane.flows import Flow
from interface_flow import Interfaces
from corrpre_postcts_flow import ElectricalPostCTS,CORNERS
from ack_chip_branches_flow import BranchSTA
ECO = '\nset block [ord::get_db_block]\nset before {}\nset places {}\nforeach inst [$block getInsts] {\n set pins {}\n foreach pin [$inst getITerms] {dict set pins [[$pin getMTerm] getName] [$pin getNet]}\n dict set before [$inst getName] [list [[$inst getMaster] getName] $pins]\n dict set places [$inst getName] [list [$inst getLocation] [$inst getOrient] [$inst getPlacementStatus]]\n if {[$inst getPlacementStatus] eq "PLACED"} {$inst setPlacementStatus FIRM}\n}\nset oldnets [llength [$block getNets]]\nset ports {}\nforeach port [$block getBTerms] {dict set ports [$port getName] [$port getNet]}\nset delay [$block findInst hold33182]\nif {$delay eq "NULL" || [[$delay getMaster] getName] ne "sg13g2_dlygate4sd3_1"} {error "Wrong existing noninverting delay"}\nset upstream [[$delay findITerm A] getNet]\nset downstream [[$delay findITerm X] getNet]\nif {$upstream eq "NULL" || $downstream eq "NULL" || $upstream eq $downstream} {error "Invalid delay topology"}\nset resolved {}\nforeach pin [get_pins -hierarchical *] {\n set name [get_full_name $pin]\n if {$name in {{$abc$734931$auto$blifparse.cc:397:parse_blif$738684/B} {$abc$734931$auto$blifparse.cc:397:parse_blif$805438/A}}} {\n  if {[dict exists $resolved $name]} {error "Ambiguous pin identity"}\n  dict set resolved $name [sta::sta_to_db_pin $pin]\n }\n}\nif {[dict size $resolved]!=2} {error "Incomplete exact sink identity"}\nset critical [dict get $resolved {$abc$734931$auto$blifparse.cc:397:parse_blif$738684/B}]\nset retained [dict get $resolved {$abc$734931$auto$blifparse.cc:397:parse_blif$805438/A}]\nif {$critical eq "NULL" || $retained eq "NULL" || [$critical getIoType] ne "INPUT" || [$retained getIoType] ne "INPUT"} {error "Invalid native input binding"}\nif {[[[$critical getInst] getMaster] getName] ne "sg13g2_xor2_1"} {error "Wrong XOR master"}\nif {[$critical getNet] ne $downstream || [$retained getNet] ne $downstream || [llength [$downstream getITerms]]!=3 || [llength [$downstream getBTerms]]!=0 || [llength [$upstream getITerms]]!=2 || [llength [$upstream getBTerms]]!=0} {error "Measured two-load topology changed"}\nset drivers {}\nforeach pin [$upstream getITerms] {if {[$pin getIoType] eq "OUTPUT"} {lappend drivers $pin}}\nif {[llength $drivers]!=1 || [[[lindex $drivers 0] getInst] getName] ne {$auto$ff.cc:337:slice$175604}} {error "Unexpected source flop"}\n$critical disconnect\n$critical connect $upstream\nif {[$retained getNet] ne $downstream || [[$delay findITerm A] getNet] ne $upstream || [[$delay findITerm X] getNet] ne $downstream} {error "Retained delay branch changed"}\nif {[llength [$block getInsts]]!=[dict size $before] || [llength [$block getNets]]!=$oldnets} {error "Unexpected cell/net mutation"}\nforeach inst [$block getInsts] {\n set name [$inst getName]\n lassign [dict get $before $name] master pins\n if {[[$inst getMaster] getName] ne $master} {error "Original master changed"}\n foreach pin [$inst getITerms] {\n  set expected [dict get $pins [[$pin getMTerm] getName]]\n  if {$pin eq $critical} {set expected $upstream}\n  if {[$pin getNet] ne $expected} {error "Unexpected pin incidence change"}\n }\n}\nforeach port [$block getBTerms] {if {[$port getNet] ne [dict get $ports [$port getName]]} {error "Port changed"}}\nputs "NSSOC_ONLY_CRITICAL_XOR_INPUT_BYPASSES_SHARED_DELAY"\n'
RESTORE = '\nforeach inst [$block getInsts] {\n lassign [dict get $places [$inst getName]] location orientation status\n if {[$inst getLocation] ne $location || [$inst getOrient] ne $orientation} {error "Unexpected placement or orientation change"}\n $inst setPlacementStatus $status\n if {[$inst getPlacementStatus] ne $status} {error "Original placement status not restored"}\n}\nputs "NSSOC_ALL_ORIGINAL_PLACEMENT_IDENTICAL_AND_STATUSES_RESTORED"\n'
class SharedHoldECO(ElectricalPostCTS):
 id='NSSOC.SharedHoldECO'
 def get_script_path(self):
  s=Path(super().get_script_path()).read_text()
  start=s.index('# Buffer I/O');end=s.index('report_floating_nets -verbose',start)
  s=s[:start]+ECO+'\n'+s[end:]
  assert 'log_cmd repair_design' not in s and 'unset_propagated_clock [all_clocks]' not in s
  assert s.count('write_views')==1
  s=s.replace('write_views',RESTORE+'\nwrite_views')
  p=Path(self.step_dir)/'shared_hold.tcl';p.write_text(s);return str(p)
@Flow.factory.register()
class AckChipSharedHold(Interfaces):
 Steps=[SharedHoldECO]+[type('Shared'+n,(BranchSTA,),dict(id='NSSOC.Shared'+n,corner=c))for n,c in CORNERS]
if __name__=='__main__':
 from librelane.__main__ import cli
 cli()
